css:
/* Frutiger Aero · 2000 年代数字怀旧
   蓝天、草地、高光泽胶质面板、水泡与太阳光晕。所有面板都是“上亮下暗”的
   玻璃塑料质感，按钮像果冻，强调 2000 年代科技乐观主义。纯 CSS。 */

html[data-theme] {
  color-scheme: light;
  --bg: #dff4ff;
  --ink: #0d3450; --muted: #3f6a84; --dim: #6d92a8;
  --soft: #1d4f6d; --meta: #3f6a84; --bright: #04222f;
  --line: rgba(255, 255, 255, 0.85); --line2: rgba(13, 52, 80, 0.1);
  --accent: #33b7ff; --accent2: #7ee36f; --accentText: #ffffff;
  --good: #4fbf62; --warn: #ffb43d;
  --glow1: rgba(51, 183, 255, 0.3); --glow2: rgba(126, 227, 111, 0.26);
  --panel: rgba(255, 255, 255, 0.82); --panel2: rgba(233, 248, 255, 0.9);
  --dock1: rgba(255, 255, 255, 0.93); --dock2: rgba(222, 243, 255, 0.95);
  --glass: rgba(255, 255, 255, 0.7);
  --track: rgba(51, 183, 255, 0.18); --scroll: #7ec8ea; --coverbg: #e6f6ff;
  --menu: rgba(255, 255, 255, 0.97); --menu1: #ffffff; --menu2: #eaf7ff; --chev: #4f7f99;
  --edge: rgba(51, 183, 255, 0.35); --edge2: rgba(126, 227, 111, 0.4);
  --hover: rgba(51, 183, 255, 0.12); --tick: rgba(51, 183, 255, 0.35);
  --inset: rgba(255, 255, 255, 0.95); --wordactive: #04222f; --swborder: rgba(51, 183, 255, 0.5);
  --shadow-dock: 0 24px 50px -26px rgba(24, 96, 140, 0.55), inset 0 2px 0 rgba(255, 255, 255, 1), inset 0 -6px 14px rgba(51, 183, 255, 0.22);
  --serif: "Segoe UI", "Frutiger", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --bottom: 136px;
  --shell-nav: rgba(255, 255, 255, 0.9); --shell-nav2: rgba(214, 241, 255, 0.9);
  --shell-navin: #0d3450; --shell-navmuted: #4f7c96; --shell-navline: rgba(51, 183, 255, 0.25);
}

html[data-theme] body {
  background:
    radial-gradient(520px 380px at 8% -6%, rgba(255, 255, 255, 0.95), transparent 62%),
    radial-gradient(700px 700px at 84% 108%, #7ee36f 0%, #4ec95f 34%, transparent 62%),
    radial-gradient(900px 520px at 50% 118%, rgba(126, 227, 111, 0.4), transparent 60%),
    linear-gradient(180deg, #bde9ff 0%, #dff4ff 46%, #eefbff 100%);
}
html[data-theme] body::before {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: 0.7;
  background:
    radial-gradient(circle at 12% 22%, rgba(255, 255, 255, 0.85) 0 16px, rgba(255, 255, 255, 0.15) 18px, transparent 22px),
    radial-gradient(circle at 68% 12%, rgba(255, 255, 255, 0.75) 0 10px, transparent 16px),
    radial-gradient(circle at 34% 78%, rgba(255, 255, 255, 0.7) 0 26px, rgba(255, 255, 255, 0.12) 28px, transparent 34px);
}

/* 侧栏：磨砂塑料板 */
html[data-theme] .sidebar {
  margin: 14px 0 14px 14px; padding: 22px 14px;
  border: 1px solid #ffffff; border-radius: 18px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(214, 241, 255, 0.88));
  box-shadow: 0 18px 34px -22px rgba(24, 96, 140, 0.55), inset 0 2px 0 #fff, inset 0 -8px 16px rgba(51, 183, 255, 0.18);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
}
html[data-theme] .brand { padding: 2px 8px 20px; border-bottom: 1px solid rgba(51, 183, 255, 0.22); margin-bottom: 14px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong {
  font-weight: 700; color: #0d3450; text-shadow: 0 1px 0 #ffffff;
}
html[data-theme] .nav button { border-radius: 12px; color: #4f7c96; }
html[data-theme] .nav button:hover { background: rgba(255, 255, 255, 0.9); color: #0d3450; }
html[data-theme] .nav button.active {
  color: #043348; font-weight: 700;
  background: linear-gradient(180deg, #ffffff 0%, #bfe9ff 46%, #8ed4f8 100%);
  box-shadow: inset 0 2px 0 #ffffff, inset 0 -3px 8px rgba(13, 52, 80, 0.18), 0 8px 16px -12px rgba(24, 96, 140, 0.7);
}

/* 顶栏：磨砂玻璃条 */
html[data-theme] .topbar {
  margin-top: 14px; padding: 0 18px; height: 64px; border: 1px solid #fff; border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(222, 243, 255, 0.82));
  box-shadow: 0 16px 30px -24px rgba(24, 96, 140, 0.6), inset 0 2px 0 #fff;
  backdrop-filter: blur(18px) saturate(160%); -webkit-backdrop-filter: blur(18px) saturate(160%);
}
html[data-theme] .search-global { border: 1px solid #fff; border-radius: 999px; background: rgba(255, 255, 255, 0.86); box-shadow: inset 0 2px 5px rgba(24, 96, 140, 0.14); }
html[data-theme] .icon-btn { border: 1px solid #fff; border-radius: 999px; background: linear-gradient(180deg, #fff, #dff2ff); box-shadow: inset 0 1px 0 #fff, 0 4px 10px -8px rgba(24, 96, 140, 0.6); }

/* 首页 */
html[data-theme] .ledger-mast {
  margin-top: 22px; padding: 32px; border: 1px solid #ffffff; border-radius: 24px;
  background:
    radial-gradient(420px 220px at 88% -10%, rgba(255, 255, 255, 0.95), transparent 62%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(200, 238, 255, 0.86) 62%, rgba(164, 224, 255, 0.9));
  box-shadow: 0 26px 46px -30px rgba(24, 96, 140, 0.6), inset 0 3px 0 #fff, inset 0 -10px 24px rgba(51, 183, 255, 0.25);
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(40px, 5.4vw, 74px); line-height: 1;
  letter-spacing: -1px; color: #0d3450;
  text-shadow: 0 2px 0 #ffffff, 0 10px 22px rgba(24, 96, 140, 0.25);
}
html[data-theme] .ledger-mast h1 em { color: #1ba8ef; text-shadow: 0 2px 0 #ffffff; }
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #3f6a84; }

/* 卡片：胶质软面板 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid #ffffff; border-radius: 18px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(226, 245, 255, 0.84));
  box-shadow: 0 18px 32px -26px rgba(24, 96, 140, 0.55), inset 0 2px 0 #fff;
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
}
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover {
  transform: translateY(-3px);
  box-shadow: 0 26px 40px -26px rgba(24, 96, 140, 0.6), inset 0 2px 0 #fff;
}
html[data-theme] .btn {
  border: 1px solid #ffffff; border-radius: 999px;
  background: linear-gradient(180deg, #eaf9ff 0%, #9fdcfb 48%, #5cc0f2 100%);
  color: #08405d; font-weight: 700;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.95), inset 0 -3px 8px rgba(13, 52, 80, 0.18), 0 10px 18px -12px rgba(24, 96, 140, 0.7);
}
html[data-theme] .btn.primary { background: linear-gradient(180deg, #d8ffce, #7ee36f 52%, #46bd4f); color: #08401b; }
html[data-theme] .btn:active { transform: translateY(1px); box-shadow: inset 0 3px 8px rgba(13, 52, 80, 0.22); }

/* 统计 */
html[data-theme] #page-stats .page-head {
  margin: 18px 0; padding: 28px 30px; border: 1px solid #fff; border-radius: 24px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(198, 237, 255, 0.88));
  box-shadow: 0 24px 44px -30px rgba(24, 96, 140, 0.55), inset 0 3px 0 #fff;
}
html[data-theme] #page-stats .page-head h1 { font-size: clamp(32px, 4.4vw, 54px); letter-spacing: -1.2px; color: #0d3450; }
html[data-theme] #page-stats .eyebrow { color: #1ba8ef; letter-spacing: 0.28em; }
html[data-theme] #page-stats .stat {
  border: 1px solid #fff; border-radius: 18px;
  background: linear-gradient(180deg, #ffffff, #ddf2ff 70%, #c6e9ff);
  box-shadow: inset 0 2px 0 #fff, inset 0 -8px 16px rgba(51, 183, 255, 0.22), 0 14px 26px -24px rgba(24, 96, 140, 0.6);
  padding: 20px 22px;
}
html[data-theme] #page-stats .stat:before { content: none; }
html[data-theme] #page-stats .stat label { color: #3f6a84; font-weight: 700; letter-spacing: 0.14em; }
html[data-theme] #page-stats .stat strong {
  font-size: 32px; font-weight: 700; color: #0d3450; background: none; -webkit-text-fill-color: #0d3450;
  text-shadow: 0 1px 0 #fff;
}
html[data-theme] #page-stats .stat em { color: #6d92a8; }
html[data-theme] #page-stats .card { border-radius: 20px; }
html[data-theme] #page-stats .stat-bar { border-radius: 12px; background: rgba(255, 255, 255, 0.72); }
html[data-theme] #page-stats .stat-track { height: 8px; border-radius: 999px; background: rgba(13, 52, 80, 0.08); box-shadow: inset 0 2px 4px rgba(13, 52, 80, 0.16); }
html[data-theme] #page-stats .stat-track i { border-radius: 999px; background: linear-gradient(90deg, #33b7ff, #7ee36f); box-shadow: 0 0 10px rgba(51, 183, 255, 0.5); }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 30px; padding: 26px 30px; border-radius: 24px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(210, 242, 255, 0.86));
  border: 1px solid #fff; box-shadow: 0 24px 44px -30px rgba(24, 96, 140, 0.55), inset 0 3px 0 #fff;
}
html[data-theme] #page-stats .year-title { font-size: 44px; color: #0d3450; background: none; -webkit-text-fill-color: #0d3450; text-shadow: 0 2px 0 #fff; }
html[data-theme] #page-stats #echoYear { border: 1px solid #fff; border-radius: 999px; background: linear-gradient(180deg, #fff, #cdeeff); color: #0d3450; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid #fff; border-radius: 16px; background: rgba(255, 255, 255, 0.8); }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid #cdeeff; border-radius: 10px; background: #f6fcff; color: #0d3450;
}

/* 播放舱：水泡胶囊 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 18px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 1px solid #fff; border-radius: 28px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(210, 241, 255, 0.9));
    box-shadow: 0 26px 50px -28px rgba(24, 96, 140, 0.6), inset 0 3px 0 #fff, inset 0 -8px 18px rgba(51, 183, 255, 0.22);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn {
  border-radius: 50%; color: #fff; border: 1px solid #fff;
  background: radial-gradient(circle at 32% 26%, #a8ecff 0 12%, #33b7ff 42%, #0d7cbe 100%);
  box-shadow: inset 0 3px 6px rgba(255, 255, 255, 0.75), 0 10px 18px -10px rgba(24, 96, 140, 0.8);
}
html[data-theme] .mini-player { border: 1px solid #fff; border-radius: 999px; background: linear-gradient(180deg, #fff, #d9f1ff); box-shadow: 0 16px 28px -22px rgba(24, 96, 140, 0.6); }

html[data-theme] .cue.active .word { color: #04222f; background: linear-gradient(180deg, #eaffff, #8fe4ff); border-radius: 6px; box-shadow: inset 0 1px 0 #fff; }
html[data-theme] ::-webkit-scrollbar-thumb { background: #8fd2f0; border-radius: 999px; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: linear-gradient(180deg, #6fc7ff 0%, #9fe0ff 42%, #d9f6d2 72%, #8fd96a 100%); color: #06263c; }
html[data-theme] .wp-bg { filter: blur(30px) saturate(200%) brightness(1.4); opacity: .42; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(120,205,255,.9) 0%, rgba(160,225,255,.78) 48%, rgba(214,246,210,.68) 76%, rgba(110,200,255,.9) 100%), radial-gradient(60% 50% at 76% 18%, rgba(255,255,255,.6), transparent 62%); }
html[data-theme] .wp-kicker { color: #0a4a6b; font-weight:700;letter-spacing:.2em;text-shadow:0 1px 0 rgba(255,255,255,.8); }
html[data-theme] .wp-title { color: #04243a; font-weight:800;letter-spacing:-.02em;text-shadow:0 1px 0 rgba(255,255,255,.85); }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(6,38,60,.78); }
html[data-theme] .wp-cue.active::before { background: linear-gradient(180deg, #ffffff, #7ee36f); box-shadow: 0 0 24px rgba(255,255,255,.9); width:clamp(5px,.36vw,7px);border-radius:6px;border:1px solid rgba(255,255,255,.9); }
html[data-theme] .wp-cue.active .wp-en { color: #04243a; text-shadow: 0 2px 18px rgba(255,255,255,.9); font-weight:800; }
html[data-theme] .wp-word.past { color: #04243a; }
html[data-theme] .wp-word.active { color: #06395a; background-image: linear-gradient(180deg, transparent 58%, rgba(126,227,111,.55) 58%, rgba(51,183,255,.34) 94%, transparent 94%); text-shadow: 0 0 18px rgba(255,255,255,.85); border-radius:6px; }
html[data-theme] .wp-zh { color: rgba(6,38,60,.66); font-weight:500; }
html[data-theme] .wp-label { color: rgba(6,38,60,.44); }
html[data-theme] .wpbtn { background: linear-gradient(180deg, rgba(255,255,255,.95), rgba(206,238,255,.8)); border-color: rgba(255,255,255,.95); color: #06263c; border-radius:999px;box-shadow:inset 0 1px 0 #fff,0 12px 24px -12px rgba(6,38,60,.5),0 0 0 1px rgba(51,183,255,.35);font-weight:700; }
html[data-theme] .wpbtn:hover { background: linear-gradient(180deg, #ffffff, #b9ecff); border-color: #33b7ff; color: #04243a; }
html[data-theme] .wp-shade::after { background: radial-gradient(circle at 22% 30%, rgba(255,255,255,.5) 0 3px, transparent 4px), radial-gradient(circle at 68% 62%, rgba(255,255,255,.42) 0 2px, transparent 3px), radial-gradient(circle at 84% 26%, rgba(255,255,255,.5) 0 4px, transparent 5px); }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dshead h4 { color: var(--soft, var(--muted)); }
html[data-theme] .dstile { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--ink); border-radius: 12px; }
html[data-theme] .dstile svg { stroke: var(--muted); }
html[data-theme] .dstile:hover { background: var(--hover, var(--panel2)); border-color: var(--accent); color: var(--ink); }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); }
html[data-theme] .dslabel { color: var(--muted); }
html[data-theme] .dspill, html[data-theme] .dsmute { background: var(--panel2, var(--panel)); border-color: var(--line); color: var(--soft, var(--ink)); }
html[data-theme] .dspill.on { color: var(--accent); border-color: var(--accent); }
html[data-theme] .dsrange { accent-color: var(--accent); }
html[data-theme] .iconbtn { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--muted); }
